    ('DENT101', 'Dental Orientation and Ethics', 2, 1, '1ST', 'Introduction to the dental profession, jurisprudence, infection control, and ethical codes.', 0, '{"quizzes":30,"exams":45,"practicum":15,"attendance":10}'),
    ('ANAT102', 'Head and Neck Anatomy', 3, 1, '2ND', 'Osteology, musculature, vasculature, and innervation of the head and neck.', 0, '{"quizzes":25,"exams":45,"practicum":20,"attendance":10}'),
    ('ORAL201', 'Oral Anatomy and Histology', 3, 2, '1ST', 'Microscopic and macroscopic anatomy of teeth and supporting structures.', 0, '{"quizzes":25,"exams":40,"practicum":25,"attendance":10}'),
    ('DMAT202', 'Dental Materials', 3, 2, '2ND', 'Properties, manipulation, and clinical selection of restorative and impression materials.', 0, '{"quizzes":20,"exams":40,"practicum":30,"attendance":10}'),
    ('CLIN301', 'Prosthodontics I', 3, 3, '1ST', 'Complete denture fabrication, impressions, jaw relations, and occlusion principles.', 1, '{"quizzes":20,"exams":30,"practicum":40,"attendance":10}'),
    ('CLIN302', 'Periodontics I', 3, 3, '2ND', 'Diagnosis and non-surgical management of periodontal diseases.', 1, '{"quizzes":20,"exams":30,"practicum":40,"attendance":10}'),
    ('CLIN401', 'Clinical Dentistry I', 4, 4, '1ST', 'Comprehensive clinical patient care, restorative procedures, and oral surgery practicum.', 1, '{"quizzes":15,"exams":25,"practicum":50,"attendance":10}'),
