), ins AS (
    INSERT INTO class_sections (cs_name, course_id, instructor_user_id, secretary_user_id, semester, school_year,
                                year_level, lab_room, lec_room, block, status, term_code, term_start_date, term_end_date)
    SELECT v.cs_name, c.course_id, v.instructor_user_id::integer,
           v.secretary_user_id::integer, v.semester, v.school_year, v.year_level::smallint, v.lab_room, v.lec_room, v.block,
           'Active', v.term_code, v.term_start_date::date, v.term_end_date::date
      FROM v JOIN courses c ON c.course_code = v.course_code
     WHERE (SELECT go FROM seed_run)
     ORDER BY v.ord
    RETURNING cs_id, cs_name, school_year, semester
)
INSERT INTO seed_cs SELECT school_year || '|' || semester || '|' || cs_name, cs_id FROM ins;

