    INSERT INTO assessments (cs_id, title, type, grading_period, max_score, weight, due_date, status)
    SELECT sc.cs_id, v.title, v.type, v.grading_period, v.max_score::numeric, v.weight::numeric, v.due_date::date, v.status
      FROM v JOIN seed_cs sc ON sc.ckey = v.ckey ORDER BY v.ord
    RETURNING assessment_id, cs_id, title
)
INSERT INTO seed_asm SELECT sc.ckey, ins.title, ins.assessment_id FROM ins JOIN seed_cs sc ON sc.cs_id = ins.cs_id;

